const raw = $input.first().json;
let body = raw.body ?? raw.data ?? raw.payload ?? raw;
if (body?.type === 'InboundMessage' && String(body.messageType || '').toUpperCase().includes('SMS')) {
  body = {
    client_slug: 'volt-n-vent',
    contact_id: body.contactId,
    message_body: body.body,
    location_id: body.locationId,
    conversation_id: body.conversationId,
    message_type: 'SMS',
    phone: body.from
  };
}

function str(v) {
  if (v == null) return '';
  return String(v).trim();
}
function pick(obj, ...keys) {
  if (!obj || typeof obj !== 'object') return '';
  for (const k of keys) {
    const v = obj[k];
    if (v != null && str(v) !== '' && !str(v).includes('{{')) return str(v);
  }
  return '';
}

const contactId = pick(body, 'contact_id', 'contactId', 'contactid')
  || pick(body.contact, 'id', 'contactId', 'contact_id')
  || pick(body.Contact, 'id', 'contactId');
const messageBody = pick(body, 'message_body', 'messageBody', 'body', 'text', 'message', 'sms_body', 'reply')
  || pick(body.message, 'body', 'text', 'message')
  || pick(body.Message, 'body', 'text')
  || pick(body, 'last_message_body', 'lastMessageBody');
const locationId = pick(body, 'location_id', 'locationId', 'locationid')
  || pick(body.location, 'id', 'locationId')
  || pick(body.Location, 'id');

if (!messageBody) {
  throw new Error('GHL webhook missing message. Map message_body using { } picker (Message → Body). Raw keys: ' + Object.keys(body || {}).join(', '));
}
if (!contactId) {
  throw new Error('GHL webhook missing contact. Map contact_id using { } picker (Contact → Id). Raw keys: ' + Object.keys(body || {}).join(', '));
}

return [{
  json: {
    client_slug: pick(body, 'client_slug') || 'volt-n-vent',
    location_id: locationId,
    ghl_contact_id: contactId,
    ghl_conversation_id: pick(body, 'conversation_id', 'conversationId') || pick(body.conversation, 'id'),
    message_body: messageBody,
    message_type: pick(body, 'message_type', 'messageType') || 'SMS',
    phone: pick(body, 'phone', 'contact_phone', 'phoneNumber') || pick(body.contact, 'phone'),
    first_name: pick(body, 'first_name', 'firstName') || pick(body.contact, 'firstName', 'first_name'),
    last_name: pick(body, 'last_name', 'lastName') || pick(body.contact, 'lastName', 'last_name'),
    channel: 'sms',
    dedupe_key: pick(body, 'dedupe_key') || `${contactId}:${pick(body, 'message_ts') || ''}:${messageBody.slice(0, 120)}`
  }
}];

const norm = $('Normalize Input').first().json;
const session = $('Start Session').first().json;
const rows = $('Load Alex Config').first().json;
const config = Array.isArray(rows) ? rows[0] : rows;
if (!config || !config.is_active) throw new Error('Config missing');
const text = (norm.message_body || '').toLowerCase().trim();
const stopWords = config.sms_opt_out_keywords || ['stop','unsubscribe','cancel','end','quit'];
const escalation = config.escalation_keywords || [];
const softNo = ['not interested','no thanks','leave me alone','stop bothering','dont text','don\'t text'];
const leadSourceAsk = /how did you get my (number|info)|where did you get my (number|info)|why are you (texting|contacting) me|never (signed up|contacted you)|didn'?t sign up/.test(text);
const reviewConcern = /\b(google review|yelp|bbb|bad review|leave a review|report you|scam|stop spamming)\b/.test(text);
let route = 'ai';
let reply_text = '';
if (stopWords.some(w => text === w || text.startsWith(w + ' '))) {
  route = 'stop';
  reply_text = 'You\'re all set — you won\'t get more texts from us. Reply HELP if you need anything.';
} else if (text === 'help') {
  route = 'help';
  reply_text = config.sms_help_reply || 'Volt N Vent: Reply STOP to opt out. Call 702-808-8861.';
} else if (reviewConcern) {
  route = 'ai';
} else if (escalation.some(k => text.includes(String(k).toLowerCase())) && !leadSourceAsk) {
  route = 'handoff';
  reply_text = "Got it — I'll have someone from our team reach out shortly. You can also call us at 702-808-8861.";
} else if (softNo.some(p => text.includes(p))) {
  route = 'ai';
}
const playbook = typeof config.conversation_playbook === 'string' ? JSON.parse(config.conversation_playbook) : (config.conversation_playbook || {});
return [{
  json: {
    ...norm,
    ...session,
    config,
    playbook,
    route,
    reply_text,
    lead_source_asked: leadSourceAsk,
    chat_history: session.history || [],
    system_prompt: config.system_prompt,
    model: config.model || 'gpt-4.1-mini',
    temperature: Number(config.temperature) || 0.55
  }
}];

const j = $input.first().json;
const session = $('Start Session').first().json;
const history = Array.isArray(j.chat_history) ? j.chat_history : [];
const priorFromHistory = history.filter(h => h.role === 'assistant').length;
const priorAssistant = Math.max(Number(session.prior_assistant_count ?? 0), priorFromHistory);
const assistantMsgs = history.filter(h => h.role === 'assistant').map(h => String(h.content || ''));
const assistantBlob = assistantMsgs.join(' ').toLowerCase();
const threadBlob = history.map(h => String(h.content || '')).join(' ').toLowerCase();
const empathyUsed = /sorry to hear|ah man|that's rough|must be frustrating|sorry about that|sorry youre dealing/.test(assistantBlob);
const heyUsed = assistantMsgs.some(t => /^hey[,!\s]/i.test(t.trim()));
const userText = String(j.message_body || '').toLowerCase().trim();

const wellnessContext = /wellness|29\.95|\$29|\$30|checkup|check-up|preventative visit|wellness check/.test(threadBlob);
const asksWhyPay = /why (do i|would i|should i) pay|why.*(29|pay|fee|charge)|what am i paying|why that (price|much)|what'?s the catch|why so cheap/.test(userText);
const asksWellnessDirect = /what (is|'?s) (a |an |the )?wellness|wellness check|hvac wellness|what do you check|what does the (check|visit)|what happens (on|during)|what'?s included|static pressure|what exactly|explain (the |this |your )?(wellness|check|offer|visit)|tell me (more )?about (the |this )?(wellness|check|offer|visit)/.test(userText);
const asksVagueFollowUp = wellnessContext && /what (is|does) (it|that|this)|what'?s that|what do you mean|tell me more|how does (it|that) work|what is that|whats that|what does that mean/.test(userText);
const asksComponents = /compressor|refrigerant|coil|condenser|duct|fan motor|lungs|blood pressure|what parts|what components|components do you/.test(userText);

const wellnessTopic = asksWhyPay
  ? 'why_pay'
  : asksComponents && (wellnessContext || asksWellnessDirect)
    ? 'hvac_components'
    : asksWellnessDirect || asksVagueFollowUp
      ? 'what_is_wellness_check'
      : null;

let wo = j.config?.wellness_offer;
if (typeof wo === 'string') { try { wo = JSON.parse(wo); } catch { wo = {}; } }
wo = wo || {};
const ku = wo.knowledge_usage || {};
const topic = wellnessTopic && ku.topics ? ku.topics[wellnessTopic] : null;

const leadNote = j.lead_source_asked
  ? 'They asked how we got their info — answer briefly per playbook only.'
  : 'Never mention lead sources or DNC unless they explicitly asked.';

let phaseNote = priorAssistant === 0
  ? 'FIRST reply: ultra casual. Sympathy ONCE max if they have a problem. No Hey required. No company intro unless outbound drip context.'
  : 'ONGOING: no Hey, no intro, no company name. Reply to NEW info only.';

let antiRepeat = '';
if (empathyUsed) antiRepeat += 'No more sympathy phrases (sorry to hear / ah man). ';
if (heyUsed || priorAssistant > 0) antiRepeat += 'Do NOT start with Hey — use Got it / Ok / Yeah / So or jump straight in. ';
if (priorAssistant > 0) antiRepeat += 'Do NOT re-ask answered questions. Do NOT repeat your last message. ';
if (/static pressure|blood pressure/.test(assistantBlob) && (asksWellnessDirect || asksVagueFollowUp)) {
  antiRepeat += 'You already explained static pressure — add a different detail (components, preventative, diagnostic) or keep shorter. ';
}

let triageHint = '';
if (/not cooling|no ac|no heat|won't cool|emergency|asap|103|110 degrees|burning smell|water leak|unit died/.test(userText)) {
  triageHint = 'TRIAGE: Service/emergency — help with their problem first. Do NOT pitch wellness. ';
} else if (/maintenance plan|annual service|tune.?up|routine maintenance|service my (ac|unit)|check my (ac|unit)/.test(userText)) {
  triageHint = 'TRIAGE: Maintenance/service request — book or qualify. Do NOT default to wellness drip script. ';
} else if (/quote|how much.*(install|replace|new unit)|financing|buy a (new )?system|good better best/.test(userText)) {
  triageHint = 'TRIAGE: Sales/quote — warm handoff, no job pricing in SMS. ';
} else if (/not interested|no thanks|stop texting|leave me alone|wrong number|don't text/.test(userText)) {
  triageHint = 'TRIAGE: Low interest — polite close, no pitch. ';
} else if (wellnessContext && /^(yes|yeah|yep|ok|okay|sure|interested|book|schedule)\b/.test(userText)) {
  triageHint = 'TRIAGE: Wellness campaign interest — book window, one question at a time. ';
}

let wellnessHint = '';
if (wellnessTopic) {
  wellnessHint = `IMPORTANT: They asked about ${wellnessTopic}. You MUST answer clearly in 1-2 casual sentences — never deflect. `;
  if (topic && Array.isArray(topic.fragments)) {
    wellnessHint += `Use 1-2 of these ideas (paraphrase, do NOT dump all): ${topic.fragments.slice(0, 6).join(' | ')}\\n`;
  }
}

const preamble = `SMS rules (highest priority):\\n- ${phaseNote}\\n- ${triageHint}${antiRepeat}${wellnessHint}${leadNote}\\n- Sound human, casual, knowledgeable. Light humor ok. Usually 1-2 short sentences; up to ~160 chars if explaining something they asked.\\n`;

const msgs = [{ role: 'system', content: preamble + '\\n---\\n\\n' + (j.system_prompt || '') }];
for (const h of history) {
  if (h && h.role && h.content && String(h.content).trim()) {
    msgs.push({ role: h.role, content: String(h.content).trim() });
  }
}
const last = msgs[msgs.length - 1];
if (!last || last.role !== 'user' || last.content !== j.message_body) {
  msgs.push({ role: 'user', content: j.message_body });
}

const maxTok = wellnessTopic ? 160 : 80;
const body = {
  model: j.model || 'gpt-4.1-mini',
  temperature: j.temperature || 0.6,
  max_tokens: maxTok,
  messages: msgs,
};

return [{ json: { ...j, openai_body: body, wellness_topic: wellnessTopic } }];

const guard = $('Guardrails + Route').first().json;
const fallback = "Sure, I can help ya — what's going on?";
let reply = guard.reply_text || '';
let conversation_mode = guard.route === 'handoff' ? 'human_escalation' : 'general_cs';
let language = 'en';
let needs_handoff = guard.route === 'handoff';
if (guard.route === 'ai') {
  const oai = $input.first().json;
  const err = oai.error?.message || oai.message;
  if (err && !oai.choices) {
    reply = fallback;
  } else {
    reply = oai.choices?.[0]?.message?.content?.trim() || fallback;
  }
  const modeMatch = reply.match(/\|\|MODE:([a-z_]+)\|\|/i);
  const langMatch = reply.match(/\|\|LANG:([a-z-]+)\|\|/i);
  if (modeMatch) conversation_mode = modeMatch[1];
  if (langMatch) language = langMatch[1];
  if (conversation_mode === 'human_escalation' || conversation_mode === 'sales_purchase' || conversation_mode === 'review_recovery') needs_handoff = true;
  reply = reply.replace(/\|\|MODE:[a-z_]+\|\|/gi, '').replace(/\|\|LANG:[a-z-]+\|\|/gi, '').trim();
  if (reply.length > 480) reply = reply.slice(0, 477) + '...';
}
return [{ json: { ...guard, reply_text: reply, conversation_mode, language, needs_handoff } }];

/**
 * n8n Code node: GHL CRM Sync
 * Adds contact note + creates/updates Marketing Pipeline opportunity stage.
 * Requires GHL httpHeaderAuth credential on this node.
 */
const item = $input.first().json;
const configRow = item.config || $('Load Alex Config').first().json;
const config = Array.isArray(configRow) ? configRow[0] : configRow;
const meta = typeof config?.metadata === 'string' ? JSON.parse(config.metadata) : (config?.metadata || {});
const crm = meta.ghl_crm_sync || {};

if (!crm.enabled || !crm.pipeline_id) {
  return [{ json: { ...item, crm_sync: { skipped: true, reason: 'crm_not_configured' } } }];
}

const cred = await this.getCredentials('httpHeaderAuth');
const token = String(cred?.value || '').trim();
const headers = {
  Authorization: token.toLowerCase().startsWith('bearer') ? token : `Bearer ${token}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};

const locationId = crm.location_id || item.location_id || config.ghl_location_id;
const contactId = item.ghl_contact_id;
if (!contactId || !locationId) {
  return [{ json: { ...item, crm_sync: { skipped: true, reason: 'missing_contact_or_location' } } }];
}

const userText = String(item.message_body || '').toLowerCase();
const replyText = String(item.reply_text || '').toLowerCase();
const mode = item.conversation_mode || 'general_cs';
const route = item.route || 'ai';
const combined = `${userText} ${replyText}`;

function pickDispositionKey() {
  if (route === 'stop') return 'opt_out';
  if (/not interested|no thanks|wrong number|leave me alone|stop texting|dont text/.test(userText)) return 'not_interested';
  if (item.needs_handoff || mode === 'human_escalation' || route === 'handoff') return 'human_handoff';
  if (mode === 'sales_purchase') return 'sales_handoff';
  if (mode === 'emergency_dispatch' || /not cooling|no ac|no heat|emergency|asap|burning smell/.test(userText)) return 'urgent_service';
  if (/book|schedule|appointment|tomorrow|monday|tuesday|wednesday|thursday|friday|8-12|12-4|morning|afternoon/.test(combined)) return 'appointment_set';
  if (mode === 'wellness_drip' || /wellness|29\.95|\$29|\$30/.test(combined)) return 'wellness_interested';
  if (Number(item.prior_assistant_count || 0) === 0 && route === 'ai') return 'new_contact';
  return 'engaged';
}

const dispositionKey = pickDispositionKey();
const disposition = crm.dispositions?.[dispositionKey] || { label: dispositionKey };
const stageId = crm.stage_ids?.[dispositionKey] || crm.stage_ids?.engaged || crm.stage_ids?.new_contact || null;

const stamp = new Date().toISOString().replace('T', ' ').slice(0, 16);
const noteBody = [
  `[${crm.note_prefix || 'Alex SMS'}] ${stamp}`,
  `Disposition: ${disposition.label || dispositionKey}`,
  `Mode: ${mode}${item.needs_handoff ? ' | Handoff: yes' : ''}`,
  `Customer: ${String(item.message_body || '').slice(0, 500)}`,
  `Alex: ${String(item.reply_text || '').slice(0, 500)}`,
].join('\n');

const results = { disposition_key: dispositionKey, disposition_label: disposition.label, stage_id: stageId, note: null, opportunity: null, errors: [] };

const http = this.helpers.httpRequest.bind(this);

try {
  const noteRes = await http({
    method: 'POST',
    url: `https://services.leadconnectorhq.com/contacts/${contactId}/notes`,
    headers,
    body: { body: noteBody },
    json: true,
  });
  results.note = noteRes?.note?.id || 'created';
} catch (e) {
  results.errors.push({ step: 'note', message: String(e.message || e) });
}

if (stageId) {
  try {
    const search = await http({
      method: 'GET',
      url: 'https://services.leadconnectorhq.com/opportunities/search',
      headers,
      qs: {
        location_id: locationId,
        contact_id: contactId,
        pipeline_id: crm.pipeline_id,
        limit: 1,
        status: 'all',
      },
      json: true,
    });
    const existing = (search?.opportunities || [])[0];
    const oppName = `SMS — ${disposition.label || dispositionKey}`;

    if (existing?.id) {
      await http({
        method: 'PUT',
        url: `https://services.leadconnectorhq.com/opportunities/${existing.id}`,
        headers,
        body: {
          pipelineId: crm.pipeline_id,
          pipelineStageId: stageId,
          name: oppName,
        },
        json: true,
      });
      results.opportunity = { action: 'updated', id: existing.id, stageId };
    } else {
      const created = await http({
        method: 'POST',
        url: 'https://services.leadconnectorhq.com/opportunities/',
        headers,
        body: {
          pipelineId: crm.pipeline_id,
          locationId,
          name: oppName,
          pipelineStageId: stageId,
          status: 'open',
          contactId,
        },
        json: true,
      });
      results.opportunity = { action: 'created', id: created?.opportunity?.id || created?.id, stageId };
    }
  } catch (e) {
    results.errors.push({ step: 'opportunity', message: String(e.message || e) });
  }
} else {
  results.errors.push({ step: 'opportunity', message: 'no_stage_id_mapped — run setup-ghl-marketing-pipeline.mjs' });
}

return [{ json: { ...item, crm_sync: results } }];
